def target_weights(price_panel, vol_window=60):
    rets = price_panel.pct_change().tail(vol_window)
    inv = (1.0 / rets.std()).replace([np.inf, -np.inf], np.nan)
    return (inv / inv.sum()).fillna(0.0)

