def managed(r):
    """vol-target 10% (sólo usa el capital necesario) + throttle por drawdown."""
    lev = (0.10 / np.sqrt(252) / r.rolling(60).std().shift(1)).clip(0, 1.5).fillna(0.5)
    eq = 1.0; peak = 1.0; out = []
    for dt in r.index:
        thr = 0.5 if eq < peak * 0.85 else 1.0        # mitad de exposición si cae >15% del pico
        rr = lev.loc[dt] * thr * r.loc[dt]
        eq *= (1 + rr); peak = max(peak, eq); out.append(rr)
    return pd.Series(out, index=r.index)

